<?php
namespace App\Services;use App\Config\Database;use App\Payments\PaymentManager;
final class DepositService{public function create(int $uid,string $gateway,float $amount):array{if($amount<1000)throw new \InvalidArgumentException('Minimal deposit Rp1.000');$db=Database::get();$g=$db->prepare('SELECT id FROM payment_gateways WHERE code=? AND is_active=1');$g->execute([$gateway]);if(!$g->fetch())throw new \RuntimeException('Metode pembayaran tidak aktif');$no='DEP-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$exp=date('Y-m-d H:i:s',time()+900);$db->prepare('INSERT INTO deposits(deposit_number,user_id,gateway,amount,status,expires_at) VALUES(?,?,?,?,"pending",?)')->execute([$no,$uid,$gateway,$amount,$exp]);$id=(int)$db->lastInsertId();$d=['id'=>$id,'deposit_number'=>$no,'amount'=>$amount,'gateway'=>$gateway,'expires_at'=>$exp];return $d+['payment'=>(new PaymentManager())->gateway($gateway)->create($d)];}public function settle(int $id,string $externalId,array $payload=[]):void{$db=Database::get();$db->beginTransaction();try{$q=$db->prepare('SELECT * FROM deposits WHERE id=? FOR UPDATE');$q->execute([$id]);$d=$q->fetch();if(!$d)throw new \RuntimeException('Deposit tidak ditemukan');if($d['status']==='paid'){$db->commit();return;}if($d['status']!=='pending')throw new \RuntimeException('Deposit tidak dapat diselesaikan');WalletService::move($db,(int)$d['user_id'],(float)$d['amount'],'deposit',$d['deposit_number'],'deposit:'.$id);$db->prepare('UPDATE deposits SET status="paid",provider_reference=?,idempotency_key=?,raw_payload=?,settled_at=NOW() WHERE id=?')->execute([$externalId,'deposit:'.$id,json_encode($payload),$id]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}}
